const http = require('node:http');
const { DatabaseSync } = require('node:sqlite');
const fs = require('node:fs');
const path = require('node:path');

const PORT = process.env.PORT || 3000;
const DATA_DIR = path.join(__dirname, 'data');
fs.mkdirSync(DATA_DIR, { recursive: true });

const db = new DatabaseSync(path.join(DATA_DIR, 'todos.db'));
db.exec(`
  CREATE TABLE IF NOT EXISTS todos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    done INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )
`);

const json = (res, status, body) => {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
};

const readBody = (req) => new Promise((resolve, reject) => {
  let data = '';
  req.on('data', (c) => { data += c; });
  req.on('end', () => {
    try { resolve(data ? JSON.parse(data) : {}); }
    catch { reject(new Error('invalid JSON')); }
  });
  req.on('error', reject);
});

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const { pathname } = url;

  // API
  const apiMatch = pathname.match(/^\/api\/todos(?:\/(\d+))?$/);
  if (apiMatch) {
    try {
      if (req.method === 'GET' && !apiMatch[1]) {
        const rows = db.prepare('SELECT id, text, done, created_at FROM todos ORDER BY id DESC').all();
        return json(res, 200, rows);
      }
      if (req.method === 'POST' && !apiMatch[1]) {
        const body = await readBody(req);
        const text = String(body.text ?? '').trim();
        if (!text) return json(res, 400, { error: 'text required' });
        const r = db.prepare('INSERT INTO todos (text) VALUES (?)').run(text);
        const row = db.prepare('SELECT id, text, done, created_at FROM todos WHERE id = ?').get(r.lastInsertRowid);
        return json(res, 201, row);
      }
      if (req.method === 'PATCH' && apiMatch[1]) {
        const id = Number(apiMatch[1]);
        const body = await readBody(req);
        if (typeof body.done === 'boolean') {
          db.prepare('UPDATE todos SET done = ? WHERE id = ?').run(body.done ? 1 : 0, id);
        }
        if (typeof body.text === 'string' && body.text.trim()) {
          db.prepare('UPDATE todos SET text = ? WHERE id = ?').run(body.text.trim(), id);
        }
        const row = db.prepare('SELECT id, text, done, created_at FROM todos WHERE id = ?').get(id);
        if (!row) return json(res, 404, { error: 'not found' });
        return json(res, 200, row);
      }
      if (req.method === 'DELETE' && apiMatch[1]) {
        const id = Number(apiMatch[1]);
        const r = db.prepare('DELETE FROM todos WHERE id = ?').run(id);
        if (r.changes === 0) return json(res, 404, { error: 'not found' });
        return json(res, 204, null); // 204 with body null -> end('')? JSON.stringify(null)='null' hmm
      }
      return json(res, 405, { error: 'method not allowed' });
    } catch (e) {
      return json(res, e.message === 'invalid JSON' ? 400 : 500, { error: e.message });
    }
  }

  // Static
  if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
    const html = fs.readFileSync(path.join(__dirname, 'public', 'index.html'));
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return res.end(html);
  }
  json(res, 404, { error: 'not found' });
});

server.listen(PORT, () => console.log(`Todo app: http://localhost:${PORT}`));
```

